css:
:root {
  --bg: #f2f3ef;
  --surface: #fdfdfb;
  --surface-mute: #f7f8f4;
  --ink: #141917;
  --secondary: #46504a;
  --muted: #5f6a63;
  --faint: #8a938c;
  --line: #e3e6e0;
  --line-strong: #d3d8d1;
  --accent: #0d684d;
  --accent-ink: #0a4e3a;
  --accent-soft: #e8f0ea;
  --good: #0d684d;
  --bad: #a34035;
  --mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
  --sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --radius: 11px;
}

*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 14px;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: hidden;
}

a, button { font: inherit; color: inherit; }
a { text-decoration: none; }
button { cursor: pointer; }

:where(a, button):focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.topbar {
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 0 24px;
  background: #fbfbf8;
  border-bottom: 1px solid var(--line);
}

.brand {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  border-radius: 6px;
}

.brand-mark {
  width: 23px;
  height: 23px;
  flex: none;
  display: grid;
  place-items: center;
  background: var(--ink);
  border-radius: 6.5px;
}

.brand-mark svg {
  width: 16px;
  height: 16px;
  display: block;
}

.brand-name {
  font-size: 17px;
  font-weight: 650;
  letter-spacing: -0.03em;
  line-height: 1;
}

.brand-tag {
  margin-left: 2px;
  padding-left: 12px;
  border-left: 1px solid var(--line-strong);
  font-size: 12px;
  font-weight: 450;
  letter-spacing: 0.005em;
  color: var(--muted);
  white-space: nowrap;
}

.topbar-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: none;
}

.range-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 34px;
  padding: 0 10px;
  background: var(--surface);
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  color: var(--ink);
  font-size: 12.5px;
  font-weight: 500;
  letter-spacing: -0.005em;
  white-space: nowrap;
  transition: border-color 140ms ease, background-color 140ms ease;
}

.range-btn:hover {
  border-color: #c3cac2;
  background: #ffffff;
}

.range-btn svg {
  color: var(--muted);
  flex: none;
}

.avatar {
  width: 31px;
  height: 31px;
  flex: none;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid rgba(10, 78, 58, 0.28);
  border-radius: 50%;
  background: linear-gradient(145deg, #337c63 0%, #12583f 100%);
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.13);
  color: #ffffff;
  font-size: 10.5px;
  font-weight: 650;
  letter-spacing: 0.03em;
  line-height: 1;
}

.shell {
  display: grid;
  grid-template-columns: 212px minmax(0, 1fr);
  min-height: calc(100vh - 64px);
}

.sidebar {
  padding: 17px 13px 20px;
  background: var(--surface-mute);
  border-right: 1px solid var(--line);
}

.nav {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.nav-link {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  height: 38px;
  padding: 0 10px;
  border-radius: 8px;
  color: var(--secondary);
  font-size: 13.5px;
  font-weight: 500;
  letter-spacing: -0.004em;
  white-space: nowrap;
  transition: background-color 140ms ease, color 140ms ease;
}

.nav-link svg {
  width: 17px;
  height: 17px;
  flex: none;
  color: var(--faint);
  transition: color 140ms ease;
}

.nav-link:hover {
  background: #eef0ea;
  color: var(--ink);
}

.nav-link:hover svg { color: var(--secondary); }

.nav-link.is-active {
  background: #e9ede6;
  color: var(--ink);
  font-weight: 600;
}

.nav-link.is-active svg { color: var(--accent); }

.nav-link.is-active::after {
  content: "";
  width: 5px;
  height: 5px;
  margin-left: auto;
  border-radius: 50%;
  background: var(--accent);
}

.main {
  min-width: 0;
  padding: 24px 28px 40px;
}

.main-inner {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
}

.page-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin: 2px 0 18px;
}

h1 {
  margin: 0;
  font-size: 24px;
  line-height: 1.1;
  font-weight: 650;
  letter-spacing: -0.028em;
}

.kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 12px;
}

.kpi {
  position: relative;
  min-width: 0;
  padding: 16px 17px 15px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: 0 1px 0 rgba(20, 25, 23, 0.02);
}

.kpi-label {
  display: block;
  padding-right: 24px;
  color: var(--muted);
  font-size: 13px;
  font-weight: 530;
  line-height: 1.2;
  letter-spacing: -0.003em;
}

.kpi-value {
  margin: 10px 0 7px;
  color: var(--ink);
  font-size: 30px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: -0.032em;
  font-variant-numeric: tabular-nums;
}

.kpi-delta {
  margin: 0;
  font-family: var(--mono);
  font-size: 12.5px;
  font-weight: 500;
  line-height: 1;
  letter-spacing: -0.01em;
}

.kpi-delta.is-good { color: var(--good); }
.kpi-delta.is-bad { color: var(--bad); }

.kpi-icon {
  position: absolute;
  top: 15px;
  right: 15px;
  width: 16px;
  height: 16px;
  color: #949d96;
}

.lower {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);
  gap: 12px;
  align-items: stretch;
}

.panel {
  display: flex;
  flex-direction: column;
  min-width: 0;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: 0 1px 0 rgba(20, 25, 23, 0.02);
}

.panel-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px 6px;
}

.panel-title {
  margin: 0;
  font-size: 14.5px;
  font-weight: 600;
  letter-spacing: -0.012em;
}

.panel-meta {
  color: var(--muted);
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 400;
  letter-spacing: -0.01em;
  white-space: nowrap;
}

.chart-canvas {
  position: relative;
  flex: 1;
  min-height: 248px;
  margin: 6px 10px 10px 10px;
}

#chartSvg {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.chart-grid {
  stroke: #e9ece6;
  stroke-width: 1;
  shape-rendering: crispEdges;
}

.chart-axis {
  fill: var(--muted);
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 400;
  letter-spacing: -0.01em;
}

.chart-area {
  fill: url(#chartAreaFill);
}

.chart-line {
  fill: none;
  stroke: var(--accent);
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.chart-dot {
  fill: var(--accent);
  stroke: var(--surface);
  stroke-width: 1.5;
}

.chart-halo {
  fill: var(--accent);
  opacity: 0.1;
}

.chart-endpoint {
  fill: var(--accent);
  stroke: var(--surface);
  stroke-width: 2;
}

.chart-value-label {
  fill: var(--ink);
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: -0.02em;
  font-variant-numeric: tabular-nums;
}

.hover-line {
  stroke: #b7c3ba;
  stroke-width: 1;
  stroke-dasharray: 3 3;
}

.hover-dot {
  fill: var(--accent);
  stroke: var(--surface);
  stroke-width: 2;
}

.chart-tip {
  position: absolute;
  z-index: 3;
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 5px 9px;
  border-radius: 7px;
  background: var(--ink);
  box-shadow: 0 6px 18px rgba(20, 25, 23, 0.16);
  color: #f5f8f4;
  font-size: 12px;
  line-height: 1.3;
  white-space: nowrap;
  pointer-events: none;
  transform: translate(-50%, -100%);
}

.chart-tip.below { transform: translate(-50%, 0); }
.chart-tip[hidden] { display: none; }

.tip-date {
  color: #aeb9b1;
  font-family: var(--mono);
  font-size: 12px;
}

.tip-value {
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.table-wrap {
  flex: 1;
  min-width: 0;
  padding: 2px 18px 12px;
}

table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

col.c-event { width: 44%; }
col.c-count { width: 20%; }
col.c-users { width: 20%; }
col.c-trend { width: 16%; }

thead th {
  padding: 0 0 9px;
  border-bottom: 1px solid var(--line);
  color: var(--muted);
  font-size: 12px;
  font-weight: 550;
  line-height: 1.2;
  letter-spacing: 0.005em;
  text-align: right;
  white-space: nowrap;
}

thead th:first-child { text-align: left; }

tbody td {
  height: 47px;
  padding: 0;
  border-bottom: 1px solid #eceee9;
  color: var(--secondary);
  font-size: 12.5px;
  vertical-align: middle;
}

tbody tr:last-child td { border-bottom: 0; }

tbody tr { transition: background-color 120ms ease; }
tbody tr:hover { background: var(--surface-mute); }

td.event {
  overflow: hidden;
  padding-right: 10px;
  color: var(--ink);
  font-family: var(--mono);
  font-size: 12px;
  letter-spacing: -0.015em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

td.num {
  padding-left: 8px;
  color: var(--ink);
  font-family: var(--mono);
  font-size: 12.5px;
  font-variant-numeric: tabular-nums;
  text-align: right;
  white-space: nowrap;
}

td.num.soft { color: var(--secondary); }

td.trend {
  text-align: right;
  white-space: nowrap;
}

.trend-arrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 23px;
  height: 23px;
  border-radius: 50%;
  font-family: var(--sans);
  font-size: 12px;
  font-weight: 600;
  line-height: 1;
}

.trend-arrow.up {
  background: #e9f2ec;
  color: var(--good);
}

.trend-arrow.down {
  background: #f6e9e6;
  color: var(--bad);
}

@media (max-width: 1160px) {
  .lower { grid-template-columns: minmax(0, 1fr); }
  .chart-canvas { min-height: 300px; }
}

@media (max-width: 980px) {
  .kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 760px) {
  .topbar {
    height: 58px;
    padding: 0 14px;
    gap: 10px;
  }

  .brand { gap: 8px; }
  .brand-mark { width: 22px; height: 22px; }
  .brand-name { font-size: 16px; }
  .brand-tag { display: none; }

  .topbar-actions { gap: 8px; }

  .range-btn {
    height: 32px;
    padding: 0 9px;
    gap: 6px;
    font-size: 12px;
  }

  .range-btn .chev { display: none; }

  .avatar {
    width: 29px;
    height: 29px;
    font-size: 10px;
  }

  .shell {
    grid-template-columns: minmax(0, 1fr);
    min-height: calc(100vh - 58px);
  }

  .sidebar {
    padding: 6px 10px;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .nav {
    flex-direction: row;
    gap: 2px;
  }

  .nav-link {
    flex: 1 1 0;
    justify-content: center;
    height: 41px;
    padding: 0 4px;
    gap: 0;
    font-size: 12.5px;
  }

  .nav-link svg { display: none; }
  .nav-link.is-active::after { display: none; }

  .main { padding: 19px 16px 32px; }
  .page-head { margin: 0 0 15px; }
  h1 { font-size: 22px; }

  .kpis { gap: 10px; margin-bottom: 10px; }

  .kpi { padding: 14px 14px 13px; }

  .kpi-label {
    padding-right: 20px;
    font-size: 12.5px;
  }

  .kpi-value {
    margin: 9px 0 7px;
    font-size: 25px;
  }

  .kpi-delta { font-size: 12px; }

  .kpi-icon {
    top: 13px;
    right: 13px;
    width: 15px;
    height: 15px;
  }

  .lower { gap: 10px; }

  .panel-head { padding: 14px 14px 5px; }

  .chart-canvas {
    min-height: 224px;
    margin: 4px 8px 8px 8px;
  }

  .table-wrap { padding: 2px 14px 10px; }

  tbody td { height: 45px; }

  td.event { font-size: 12px; }
  td.num { font-size: 12px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}
